/bin/bash -lc "python - <<'PY'
import csv, json, math
from collections import defaultdict, Counter
from pathlib import Path

base = Path('/app')

def read_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def num(x):
    if x is None or x == '':
        return None
    if x.isdigit() or (x.startswith('-') and x[1:].isdigit()):
        return int(x)
    try:
        v = float(x)
        if abs(v - round(v)) < 1e-9:
            return int(round(v))
        return v
    except Exception:
        return x

bookings = {r['booking_id']: r for r in read_csv(base/'data/bookings.csv')}
for r in bookings.values():
    for k in ['reveal_wave','teu','earliest_load_day','due_arrival_day','revenue','reject_penalty','medical_flag','change_penalty']:
        r[k] = int(r[k])
legs = {r['leg_id']: r for r in read_csv(base/'data/vessel_legs.csv')}
for r in legs.values():
    for k in ['depart_day','arrive_day','teu_capacity','reefer_plug_capacity','dg1_limit']:
        r[k] = int(r[k])
path_rules = {r['booking_id']: r for r in read_csv(base/'data/booking_path_rules.csv')}
for r in path_rules.values():
    r['max_transship_count'] = int(r['max_transship_count'])
    r['requires_direct'] = int(r['requires_direct'])
    r['cold_chain_preclear'] = int(r['cold_chain_preclear'])
    r['allowed_services'] = set(r['allowed_services'].split('|')) if r['allowed_services'] else set()
service_rules = {r['priority']: float(r['min_accept_rate']) for r in read_csv(base/'data/service_rules.csv')}
protected = read_csv(base/'data/protected_slots.csv')
for r in protected:
    r['min_teu'] = int(r['min_teu'])
transfer = read_csv(base/'data/transfer_limits.csv')
for r in transfer:
    r['day'] = int(r['day']); r['max_reefer_transfer_teu']=int(r['max_reefer_transfer_teu']); r['max_dg1_transfer_teu']=int(r['max_dg1_transfer_teu'])
special = {r['booking_id']: r for r in read_csv(base/'data/special_booking_rules.csv')}
for r in special.values():
    r['require_accept'] = int(r['require_accept']); r['max_legs'] = int(r['max_legs'])
ports = {r['port_id']: r for r in read_csv(base/'data/ports.csv')}
for r in ports.values():
    for k in ['initial_std','initial_reefer','yard_capacity','reefer_plug_capacity','gate_out_default','gate_in_default']:
        r[k] = int(r[k])
    for k in ['storage_cost_std','storage_cost_reefer']:
        r[k] = float(r[k])
port_limits = {(r['port_id'], int(r['day'])): r for r in read_csv(base/'data/port_day_limits.csv')}
for r in port_limits.values():
    for k in ['gate_out_limit','gate_in_limit','yard_capacity','reefer_plug_capacity']:
        r[k] = int(r[k])
customs = {(r['port_id'], int(r['day']), r['customs_group']): r for r in read_csv(base/'data/customs_inspection_windows.csv')}
for r in customs.values():
    r['max_teu'] = int(r['max_teu']); r['max_medical_reefer_teu'] = int(r['max_medical_reefer_teu']); r['inspection_cost_per_teu'] = float(r['inspection_cost_per_teu'])
lease_opts = {(r['port_id'], int(r['day']), r['container_type']): r for r in read_csv(base/'data/lease_options.csv')}
for r in lease_opts.values():
    r['max_teu'] = int(r['max_teu']); r['lease_cost_per_teu'] = float(r['lease_cost_per_teu'])
empty_cost = {(r['leg_id'], r['container_type']): r for r in read_csv(base/'data/empty_reposition_costs.csv')}
for r in empty_cost.values():
    r['cost_per_teu'] = float(r['cost_per_teu']); r['carbon_kg_per_teu'] = float(r['carbon_kg_per_teu'])


def parse_plan(path, expected_visible=None):
    rows = []
    with open(path, newline='') as f:
        rd = csv.DictReader(f)
        header = rd.fieldnames
        for row in rd:
            rows.append(row)
    findings = []
    if header "'!= ['"'row_type','item_id','decision','leg_id','port_id','day','container_type','quantity_teu']:
        findings.append(('header', 'schema', str(header), 'exact required header', 'rewrite header exactly'))
    decisions = {}
    booking_legs = defaultdict(list)
    emptys = []
    leases = []
    raw_item_rows = defaultdict(list)
    for i,row in enumerate(rows, start=2):
        key = f'{path.name}:{i}'
        raw_item_rows[row['item_id']].append((i,row))
        q = row['quantity_teu']
        try:
            qv = None if q == '' else float(q)
        except Exception:
            qv = 'BAD'
        day = row['day']
        try:
            dv = None if day == '' else int(day)
        except Exception:
            dv = 'BAD'
        rt = row['row_type']
        if rt == 'booking_decision':
            bid = row['item_id']
            if bid in decisions:
                findings.append((key, 'key coverage', f'duplicate decision for {bid}', 'exactly one decision row', 'drop duplicate or merge to one row'))
            decisions[bid] = row['decision']
            if row['decision'] not in ('accept','reject'):
                findings.append((key, 'schema', row['decision'], 'accept or reject', 'use a legal booking decision'))
            for fld in ['leg_id','port_id','day','container_type','quantity_teu']:
                if row[fld] "'!= '"'':
                    findings.append((key, 'nullability', f'{fld}={row[fld]"'!r}'"', f'{fld} blank on booking_decision', 'blank non-applicable fields'))
            if bid not in bookings:
                findings.append((key, 'identifier domain', bid, 'visible booking id', 'remove or rename to a visible booking'))
        elif rt == 'booking_leg':
            bid = row['item_id']
            booking_legs[bid].append(row)
            if row['decision'] "'!= '"'load':
                findings.append((key, 'schema', row['decision'], 'load', 'set booking_leg decision to load'))
            if bid not in bookings:
                findings.append((key, 'identifier domain', bid, 'visible booking id', 'remove orphan booking_leg or fix booking id'))
            if row['leg_id'] not in legs:
                findings.append((key, 'identifier domain', row['leg_id'], 'valid vessel leg id', 'use a published leg id'))
            for fld in ['port_id','day','container_type']:
                if row[fld] "'!= '"'':
                    findings.append((key, 'nullability', f'{fld}={row[fld]"'!r}'"', f'{fld} blank on booking_leg', 'blank non-applicable fields'))
            if qv == 'BAD' or qv is None or qv <= 0:
                findings.append((key, 'schema', row['quantity_teu'], 'positive quantity_teu', 'provide a positive booking leg quantity'))
            elif bid in bookings and abs(qv - bookings[bid]['teu']) > 1e-9:
                findings.append((key, 'booking-leg quantity', qv, bookings[bid]['teu'], 'set leg quantity equal to booking TEU on every used leg'))
        elif rt == 'empty_move':
            emptys.append(row)
            if row['decision'] "'!= '"'move':
                findings.append((key, 'schema', row['decision'], 'move', 'set empty_move decision to move'))
            if row['leg_id'] not in legs:
                findings.append((key, 'identifier domain', row['leg_id'], 'valid vessel leg id', 'use a published leg id'))
            if row['container_type'] not in ('STD','REEFER'):
                findings.append((key, 'identifier domain', row['container_type'], 'STD or REEFER', 'use a legal container type'))
            if qv == 'BAD' or qv is None or qv <= 0:
                findings.append((key, 'schema', row['quantity_teu'], 'positive quantity_teu', 'provide a positive empty move quantity'))
            if dv == 'BAD':
                findings.append((key, 'schema', row['day'], 'integer day or blank', 'fix the day value'))
            if row['port_id'] "'!= '"'':
                findings.append((key, 'nullability', f'port_id={row[\"port_id\"]"'!r}'"', 'port_id blank on empty_move', 'blank port_id on empty moves'))
        elif rt == 'lease':
            leases.append(row)
            if row['decision'] "'!= '"'lease':
                findings.append((key, 'schema', row['decision'], 'lease', 'set lease decision to lease'))
            if row['port_id'] not in ports:
                findings.append((key, 'identifier domain', row['port_id'], 'valid port id', 'use a published port id'))
            if row['container_type'] not in ('STD','REEFER'):
                findings.append((key, 'identifier domain', row['container_type'], 'STD or REEFER', 'use a legal container type'))
            if qv == 'BAD' or qv is None or qv <= 0:
                findings.append((key, 'schema', row['quantity_teu'], 'positive quantity_teu', 'provide a positive lease quantity'))
            if dv == 'BAD' or dv is None:
                findings.append((key, 'schema', row['day'], 'integer day', 'provide lease day'))
            if row['leg_id'] "'!= '"'':
                findings.append((key, 'nullability', f'leg_id={row[\"leg_id\"]"'!r}'"', 'leg_id blank on lease', 'blank leg_id on lease rows'))
        else:
            findings.append((key, 'schema', rt, 'one of booking_decision/booking_leg/empty_move/lease', 'use a valid row_type'))
    if expected_visible is not None:
        visible = {bid for bid,b in bookings.items() if b['reveal_wave'] <= expected_visible}
        missing = sorted(visible - decisions.keys())
        extra = sorted(decisions.keys() - visible)
        for bid in missing[:20]:
            findings.append((f'{path.name}:{bid}', 'key coverage', 'missing booking_decision', 'exactly one decision row for each visible booking', 'add a booking_decision row'))
        for bid in extra[:20]:
            findings.append((f'{path.name}:{bid}', 'key coverage', 'decision for non-visible booking', 'decisions only for currently visible bookings', 'remove the non-visible booking_decision'))
    for bid,dec in decisions.items():
        if bid in booking_legs and dec == 'reject':
            findings.append((f'{path.name}:{bid}', 'accepted/rejected linkage', 'reject with booking_leg rows', 'rejected bookings must not have booking_leg rows', 'remove the leg rows or accept the booking'))
        if dec == 'accept' and bid not in booking_legs:
            findings.append((f'{path.name}:{bid}', 'accepted/rejected linkage', 'accept with no booking_leg rows', 'accepted bookings need at least one booking_leg row', 'add a feasible path or reject'))
    return {'rows': rows, 'decisions': decisions, 'booking_legs': booking_legs, 'emptys': emptys, 'leases': leases, 'findings': findings}

step2 = parse_plan(base/'submissions/step2_replan.csv', expected_visible=2)
step3 = parse_plan(base/'submissions/step3_replan.csv', expected_visible=3)
initial = parse_plan(base/'submissions/initial_plan.csv', expected_visible=1)

# path/order and capacity checks on step3
findings = list(step3['findings'])
leg_booking_priority = defaultdict(float)
leg_total = defaultdict(float)
leg_reefer = defaultdict(float)
leg_dg1 = defaultdict(float)
transfer_reefer = defaultdict(float)
transfer_dg1 = defaultdict(float)
customs_load = defaultdict(float)
customs_med = defaultdict(float)
obj = Counter()

# costs from decision rows
for bid,b in bookings.items():
    dec = step3['decisions'].get(bid)
    if dec == 'accept':
        obj['revenue'] += b['revenue']
    elif dec == 'reject':
        obj['reject_penalty'] += b['reject_penalty']

for bid,dec in step3['decisions'].items():
    if bid not in bookings:
        continue
    b = bookings[bid]
    if b['medical_flag'] == 1 and b['container_type'] == 'REEFER' and dec "'!= '"'accept':
        findings.append((f'step3_replan.csv:{bid}', 'mandatory medical acceptance', dec, 'accept', 'accept the medical reefer booking and provide a feasible direct path if required'))

# priority acceptance rates
visible_by_priority = Counter(); acc_by_priority = Counter()
for bid,b in bookings.items():
    visible_by_priority[b['priority']] += 1
    if step3['decisions'].get(bid) == 'accept':
        acc_by_priority[b['priority']] += 1
for pr, rate in service_rules.items():
    lhs = acc_by_priority[pr]
    req = math.ceil(rate * visible_by_priority[pr] - 1e-12)
    # safer exact ratio check
    if visible_by_priority[pr] and lhs / visible_by_priority[pr] + 1e-12 < rate:
        findings.append((f'priority:{pr}', 'priority minimum acceptance', f'{lhs}/{visible_by_priority[pr]}={lhs/visible_by_priority[pr]:.4f}', f'>={rate:.4f}', 'accept additional visible bookings in this priority group'))

for bid, legs_rows in step3['booking_legs'].items():
    if bid not in bookings: 
        continue
    b = bookings[bid]
    path = [legs[r['leg_id']] for r in legs_rows if r['leg_id'] in legs]
    # preserve export order exactly as rows appear
    valid = True
    if not path:
        continue
    if path[0]['from_port'] "'!= b['"'origin_port']:
        findings.append((f'step3_replan.csv:{bid}', 'path origin', path[0]['from_port'], b['origin_port'], 'start the accepted path at the booking origin'))
        valid = False
    if path[-1]['to_port'] "'!= b['"'destination_port']:
        findings.append((f'step3_replan.csv:{bid}', 'path destination', path[-1]['to_port'], b['destination_port'], 'end the accepted path at the booking destination'))
        valid = False
    if path[0]['depart_day'] < b['earliest_load_day']:
        findings.append((f'step3_replan.csv:{bid}', 'earliest load', path[0]['depart_day'], f'>={b[\"earliest_load_day\"]}', 'move the first leg to a departure on or after earliest_load_day'))
        valid = False
    if path[-1]['arrive_day'] > b['due_arrival_day']:
        findings.append((f'step3_replan.csv:{bid}', 'due arrival', path[-1]['arrive_day'], f'<={b[\"due_arrival_day\"]}', 'reroute or reject the booking'))
        valid = False
    for i in range(len(path)-1):
        a,bn = path[i], path[i+1]
        if a['to_port'] "'!= bn['"'from_port']:
            findings.append((f'step3_replan.csv:{bid}', 'path continuity location', f'{a[\"to_port\"]}->{bn[\"from_port\"]}', 'same transshipment port', 'make adjacent legs connect at the same port'))
            valid = False
        if a['arrive_day'] > bn['depart_day']:
            findings.append((f'step3_replan.csv:{bid}', 'path continuity time', f'arrive {a[\"arrive_day\"]} > depart {bn[\"depart_day\"]}', 'arrive_day <= next depart_day', 'use a time-feasible ordered chain'))
            valid = False
    trans = max(0, len(path)-1)
    pr = path_rules[bid]
    if trans > pr['max_transship_count']:
        findings.append((f'step3_replan.csv:{bid}', 'max transshipments', trans, f'<= {pr[\"max_transship_count\"]}', 'shorten the path or reject the booking'))
    services = {leg['service'] for leg in path}
    bad = services - pr['allowed_services']
    if bad:
        findings.append((f'step3_replan.csv:{bid}', 'service-loop eligibility', '|'.join(sorted(bad)), '|'.join(sorted(pr['allowed_services'])), 'use only allowed services for this booking'))
    require_direct = pr['requires_direct'] == 1
    if bid in special and special[bid]['max_legs'] == 1:
        require_direct = True
    if require_direct:
        if len(path) "'!= 1 or path[0]['"'from_port'] "'!= bookings[bid]['"'origin_port'] or path[0]['to_port'] "'!= bookings[bid]['"'destination_port']:
            findings.append((f'step3_replan.csv:{bid}', 'direct-sailing rule', 'path has transshipment or is not direct', 'exactly one direct leg origin->destination', 'replace with a single direct leg or reject if impossible'))
    if bid in special:
        sp = special[bid]
        if sp['require_accept'] and step3['decisions'].get(bid) "'!= '"'accept':
            findings.append((f'step3_replan.csv:{bid}', 'special booking rule require_accept', step3['decisions'].get(bid), 'accept', 'accept the required booking'))
        if len(path) > sp['max_legs']:
            findings.append((f'step3_replan.csv:{bid}', 'special booking rule max_legs', len(path), f'<= {sp[\"max_legs\"]}', 'reduce leg count to the special-rule limit'))

    # load to capacities/objective/customs/transfers
    for leg in path:
        q = bookings[bid]['teu']
        leg_total[leg['leg_id']] += q
        leg_booking_priority[(leg['leg_id'], bookings[bid]['priority'])] += q
        if bookings[bid]['container_type'] == 'REEFER':
            leg_reefer[leg['leg_id']] += q
        if bookings[bid]['hazmat_class'] == 'DG1':
            leg_dg1[leg['leg_id']] += q
    group = pr['customs_group']
    q = bookings[bid]['teu']
    # export
    customs_load[(path[0]['from_port'], path[0]['depart_day'], group)] += q
    if bookings[bid]['medical_flag'] == 1 and bookings[bid]['container_type'] == 'REEFER' and group == 'cold_chain':
        customs_med[(path[0]['from_port'], path[0]['depart_day'], group)] += q
    # transship on arrival of intermediate legs
    for leg in path[:-1]:
        customs_load[(leg['to_port'], leg['arrive_day'], group)] += q
        if bookings[bid]['medical_flag'] == 1 and bookings[bid]['container_type'] == 'REEFER' and group == 'cold_chain':
            customs_med[(leg['to_port'], leg['arrive_day'], group)] += q
    # import final arrival
    customs_load[(path[-1]['to_port'], path[-1]['arrive_day'], group)] += q
    if bookings[bid]['medical_flag'] == 1 and bookings[bid]['container_type'] == 'REEFER' and group == 'cold_chain':
        customs_med[(path[-1]['to_port'], path[-1]['arrive_day'], group)] += q
    # transfer caps at intermediate arrival port/day
    for leg in path[:-1]:
        port = leg['to_port']; day = leg['arrive_day']
        if bookings[bid]['container_type'] == 'REEFER':
            transfer_reefer[(port, day)] += q
        if bookings[bid]['hazmat_class'] == 'DG1':
            transfer_dg1[(port, day)] += q

# empty moves capacities
for row in step3['emptys']:
    leg_id = row['leg_id']
    if leg_id not in legs:
        continue
    q = float(row['quantity_teu'])
    ctype = row['container_type']
    leg_total[leg_id] += q
    if ctype == 'REEFER':
        leg_reefer[leg_id] += q
    # day consistency if provided
    if row['day'] not in ('', str(legs[leg_id]['depart_day'])):
        findings.append((f\"step3_replan.csv:empty_move:{row['item_id']}\", 'empty move departure day', row['day'], str(legs[leg_id]['depart_day']), 'set the empty_move day to the leg departure day or leave it blank'))
    costrow = empty_cost.get((leg_id, ctype))
    if not costrow:
        findings.append((f\"step3_replan.csv:empty_move:{row['item_id']}\", 'empty move domain', f'{leg_id}|{ctype}', 'published empty-move cost row', 'use a legal leg/container_type pair'))
    else:
        obj['empty_move_cost'] += q * costrow['cost_per_teu']
        obj['carbon_kg'] += q * costrow['carbon_kg_per_teu']

for row in step3['leases']:
    q = float(row['quantity_teu'])
    key = (row['port_id'], int(row['day']), row['container_type'])
    opt = lease_opts.get(key)
    if not opt:
        findings.append((f\"step3_replan.csv:lease:{row['item_id']}\", 'lease domain', '|'.join(map(str,key)), 'published lease option', 'use a lease only where an option exists'))
    else:
        if q > opt['max_teu'] + 1e-9:
            findings.append((f\"step3_replan.csv:lease:{row['item_id']}\", 'lease capacity', q, f'<= {opt[\"max_teu\"]}', 'reduce lease TEU to the published limit'))
        obj['lease_cost'] += q * opt['lease_cost_per_teu']

# capacities
for leg_id, leg in legs.items():
    if leg_total[leg_id] > leg['teu_capacity'] + 1e-9:
        findings.append((f'leg:{leg_id}', 'vessel capacity', leg_total[leg_id], f'<= {leg[\"teu_capacity\"]}', 'reduce loaded or empty TEU on this sailing'))
    if leg_reefer[leg_id] > leg['reefer_plug_capacity'] + 1e-9:
        findings.append((f'leg:{leg_id}', 'vessel reefer capacity', leg_reefer[leg_id], f'<= {leg[\"reefer_plug_capacity\"]}', 'reduce reefer TEU on this sailing'))
    if leg_dg1[leg_id] > leg['dg1_limit'] + 1e-9:
        findings.append((f'leg:{leg_id}', 'vessel DG1 capacity', leg_dg1[leg_id], f'<= {leg[\"dg1_limit\"]}', 'reduce DG1 TEU on this sailing'))

for r in protected:
    lhs = leg_booking_priority[(r['leg_id'], r['priority'])]
    if lhs + 1e-9 < r['min_teu']:
        findings.append((f'protected:{r[\"rule_id\"]}', 'protected slot minimum', lhs, f'>= {r[\"min_teu\"]}', 'route or retain enough accepted TEU of the protected priority on this leg'))

for r in transfer:
    rr = transfer_reefer[(r['port_id'], r['day'])]
    dg = transfer_dg1[(r['port_id'], r['day'])]
    if rr > r['max_reefer_transfer_teu'] + 1e-9:
        findings.append((f'transfer:{r[\"rule_id\"]}', 'reefer transfer capacity', rr, f'<= {r[\"max_reefer_transfer_teu\"]}', 'reduce reefer transshipment volume through this port/day'))
    if dg > r['max_dg1_transfer_teu'] + 1e-9:
        findings.append((f'transfer:{r[\"rule_id\"]}', 'DG1 transfer capacity', dg, f'<= {r[\"max_dg1_transfer_teu\"]}', 'reduce DG1 transshipment volume through this port/day'))

for key, load in sorted(customs_load.items()):
    port, day, grp = key
    cap = customs.get(key)
    if not cap:
        findings.append((f'customs:{port}|{day}|{grp}', 'customs domain', load, 'published customs window', 'avoid customs usage on an unpublished port/day/group'))
        continue
    if load > cap['max_teu'] + 1e-9:
        findings.append((f'customs:{port}|{day}|{grp}', 'customs capacity', load, f'<= {cap[\"max_teu\"]}', 'reduce inspected TEU at this port/day/group'))
    med = customs_med.get(key, 0.0)
    if med > cap['max_medical_reefer_teu'] + 1e-9:
        findings.append((f'customs:{port}|{day}|{grp}', 'medical reefer customs sublimit', med, f'<= {cap[\"max_medical_reefer_teu\"]}', 'reduce medical reefer inspections or reroute in time'))
    obj['customs_cost'] += load * cap['inspection_cost_per_teu']

# Inventory / gate replay
# end-of-day inventory = previous end - departures/loads/empty moves + releases + empty arrivals + leases
inv = {}
for port, r in ports.items():
    inv[(port, 'STD')] = r['initial_std']
    inv[(port, 'REEFER')] = r['initial_reefer']

outflow = defaultdict(float)
inflow = defaultdict(float)
gate_out = defaultdict(float)
gate_in = defaultdict(float)
# bookings
for bid,legs_rows in step3['booking_legs'].items():
    if bid not in bookings or not legs_rows:
        continue
    b = bookings[bid]
    path = [legs[r['leg_id']] for r in legs_rows if r['leg_id'] in legs]
    if not path:
        continue
    q = b['teu']
    ctype = b['container_type']
    first = path[0]
    last = path[-1]
    outflow[(first['from_port'], first['depart_day'], ctype)] += q
    gate_out[(first['from_port'], first['depart_day'])] += q
    release_day = last['arrive_day'] + (1 if ctype == 'REEFER' else 0)
    inflow[(last['to_port'], release_day, ctype)] += q
    gate_in[(last['to_port'], release_day)] += q
# empty moves
for row in step3['emptys']:
    if row['leg_id'] not in legs: continue
    leg = legs[row['leg_id']]
    q = float(row['quantity_teu']); ctype = row['container_type']
    outflow[(leg['from_port'], leg['depart_day'], ctype)] += q
    inflow[(leg['to_port'], leg['arrive_day'], ctype)] += q
    gate_out[(leg['from_port'], leg['depart_day'])] += q
    gate_in[(leg['to_port'], leg['arrive_day'])] += q
# leases
for row in step3['leases']:
    if row['port_id'] not in ports or row['day']=='':
        continue
    q = float(row['quantity_teu']); ctype = row['container_type']; day = int(row['day'])
    inflow[(row['port_id'], day, ctype)] += q
    gate_in[(row['port_id'], day)] += q

# inventory over days 0..15 because customs uses 15 and reefer releases can land at 15
