    if leg_dg1[leg_id] > leg['dg1_limit'] + 1e-9:
        findings.append((f'leg:{leg_id}', 'vessel DG1 capacity', leg_dg1[leg_id], f'<= {leg[\"dg1_limit\"]}', 'reduce DG1 TEU on this sailing'))

for r in protected:
    lhs = leg_booking_priority[(r['leg_id'], r['priority'])]
    if lhs + 1e-9 < r['min_teu']:
        findings.append((f'protected:{r[\"rule_id\"]}', 'protected slot minimum', lhs, f'>= {r[\"min_teu\"]}', 'route or retain enough accepted TEU of the protected priority on this leg'))

for r in transfer:
    rr = transfer_reefer[(r['port_id'], r['day'])]
    dg = transfer_dg1[(r['port_id'], r['day'])]
    if rr > r['max_reefer_transfer_teu'] + 1e-9:
        findings.append((f'transfer:{r[\"rule_id\"]}', 'reefer transfer capacity', rr, f'<= {r[\"max_reefer_transfer_teu\"]}', 'reduce reefer transshipment volume through this port/day'))
    if dg > r['max_dg1_transfer_teu'] + 1e-9:
        findings.append((f'transfer:{r[\"rule_id\"]}', 'DG1 transfer capacity', dg, f'<= {r[\"max_dg1_transfer_teu\"]}', 'reduce DG1 transshipment volume through this port/day'))

for key, load in sorted(customs_load.items()):
    port, day, grp = key
    cap = customs.get(key)
    if not cap:
        findings.append((f'customs:{port}|{day}|{grp}', 'customs domain', load, 'published customs window', 'avoid customs usage on an unpublished port/day/group'))
        continue
    if load > cap['max_teu'] + 1e-9:
        findings.append((f'customs:{port}|{day}|{grp}', 'customs capacity', load, f'<= {cap[\"max_teu\"]}', 'reduce inspected TEU at this port/day/group'))
    med = customs_med.get(key, 0.0)
    if med > cap['max_medical_reefer_teu'] + 1e-9:
        findings.append((f'customs:{port}|{day}|{grp}', 'medical reefer customs sublimit', med, f'<= {cap[\"max_medical_reefer_teu\"]}', 'reduce medical reefer inspections or reroute in time'))
    obj['customs_cost'] += load * cap['inspection_cost_per_teu']

# Inventory / gate replay
# end-of-day inventory = previous end - departures/loads/empty moves + releases + empty arrivals + leases
inv = {}
for port, r in ports.items():
    inv[(port, 'STD')] = r['initial_std']
    inv[(port, 'REEFER')] = r['initial_reefer']

outflow = defaultdict(float)
inflow = defaultdict(float)
gate_out = defaultdict(float)
gate_in = defaultdict(float)
# bookings
for bid,legs_rows in step3['booking_legs'].items():
    if bid not in bookings or not legs_rows:
        continue
    b = bookings[bid]
    path = [legs[r['leg_id']] for r in legs_rows if r['leg_id'] in legs]
    if not path:
        continue
    q = b['teu']
    ctype = b['container_type']
    first = path[0]
    last = path[-1]
    outflow[(first['from_port'], first['depart_day'], ctype)] += q
    gate_out[(first['from_port'], first['depart_day'])] += q
    release_day = last['arrive_day'] + (1 if ctype == 'REEFER' else 0)
    inflow[(last['to_port'], release_day, ctype)] += q
    gate_in[(last['to_port'], release_day)] += q
# empty moves
for row in step3['emptys']:
    if row['leg_id'] not in legs: continue
    leg = legs[row['leg_id']]
    q = float(row['quantity_teu']); ctype = row['container_type']
    outflow[(leg['from_port'], leg['depart_day'], ctype)] += q
    inflow[(leg['to_port'], leg['arrive_day'], ctype)] += q
    gate_out[(leg['from_port'], leg['depart_day'])] += q
    gate_in[(leg['to_port'], leg['arrive_day'])] += q
# leases
for row in step3['leases']:
    if row['port_id'] not in ports or row['day']=='':
        continue
    q = float(row['quantity_teu']); ctype = row['container_type']; day = int(row['day'])
    inflow[(row['port_id'], day, ctype)] += q
    gate_in[(row['port_id'], day)] += q

# inventory over days 0..15 because customs uses 15 and reefer releases can land at 15
history = {}
for day in range(0, 16):
    for port in ports:
        for ctype in ('STD','REEFER'):
            inv[(port, ctype)] = inv[(port, ctype)] - outflow[(port, day, ctype)] + inflow[(port, day, ctype)]
            history[(port, day, ctype)] = inv[(port, ctype)]
            if inv[(port, ctype)] < -1e-9:
                findings.append((f'inventory:{port}|{day}|{ctype}', 'inventory nonnegative', inv[(port, ctype)], '>= 0', 'add leases/empty inflow earlier or reduce outbound usage'))
        limits = port_limits.get((port, day))
        if not limits:
            continue
        yard = history[(port, day, 'STD')] + history[(port, day, 'REEFER')]
        reefer_inv = history[(port, day, 'REEFER')]
        if yard > limits['yard_capacity'] + 1e-9:
            findings.append((f'yard:{port}|{day}', 'yard capacity', yard, f'<= {limits[\"yard_capacity\"]}', 'reduce ending yard inventory at this port/day'))
        if reefer_inv > limits['reefer_plug_capacity'] + 1e-9:
            findings.append((f'reefer_yard:{port}|{day}', 'yard reefer plug capacity', reefer_inv, f'<= {limits[\"reefer_plug_capacity\"]}', 'reduce reefer inventory at this port/day'))
        if gate_out[(port, day)] > limits['gate_out_limit'] + 1e-9:
            findings.append((f'gate_out:{port}|{day}', 'gate-out capacity', gate_out[(port, day)], f'<= {limits[\"gate_out_limit\"]}', 'reduce loaded/empty departures from this port/day'))
        if gate_in[(port, day)] > limits['gate_in_limit'] + 1e-9:
            findings.append((f'gate_in:{port}|{day}', 'gate-in capacity', gate_in[(port, day)], f'<= {limits[\"gate_in_limit\"]}', 'reduce arrivals/releases/leases into this port/day'))
        # holding cost on ending inventory day 0..14 only maybe, but compute all visible days 0..14
        if day <= 14:
            obj['holding_cost'] += history[(port, day, 'STD')] * ports[port]['storage_cost_std']
            obj['holding_cost'] += history[(port, day, 'REEFER')] * ports[port]['storage_cost_reefer']

# Replan diffs step2->step3
legacy = sorted([bid for bid,b in bookings.items() if b['reveal_wave'] <= 2])
